#!/usr/bin/env python3
from pathlib import Path
import sys

p=Path(sys.argv[1])
s=p.read_text()
anchor="""    }).sort((left, right) => right.score - left.score);\n    const hybridRow = rows.find((row) => tempoClose(row.bpm, hybrid.bpm)) ?? rows[0];\n"""
insert="""    }).sort((left, right) => right.score - left.score);\n    // Research-only metrical-family expansion. These candidates DO NOT participate in selection.\n    // GiantSteps reference BPM is never visible here; this is entirely signal-derived evidence.\n    const metricalRatios = [\n        [0.5, '1:2'], [2, '2:1'],\n        [2 / 3, '2:3'], [3 / 2, '3:2'],\n        [3 / 4, '3:4'], [4 / 3, '4:3'],\n        [4 / 5, '4:5'], [5 / 4, '5:4'],\n        [3 / 5, '3:5'], [5 / 3, '5:3'],\n    ];\n    const expandedSeeds = [];\n    for (const seed of candidateSeeds) {\n        expandedSeeds.push({ bpm: seed.bpm, weight: seed.weight, transform: 'direct' });\n        for (const [ratio, label] of metricalRatios) {\n            const bpm = seed.bpm * ratio;\n            if (bpm >= 55 && bpm <= 220) expandedSeeds.push({ bpm, weight: seed.weight * 0.55, transform: label });\n        }\n    }\n    const expandedClusters = [];\n    for (const seed of expandedSeeds) {\n        let cluster = expandedClusters.find((item) => tempoClose(item.bpm, seed.bpm));\n        if (!cluster) { cluster = { bpm: seed.bpm, seeds: [] }; expandedClusters.push(cluster); }\n        cluster.seeds.push(seed);\n        const weightTotal = cluster.seeds.reduce((sum, item) => sum + item.weight, 0);\n        cluster.bpm = cluster.seeds.reduce((sum, item) => sum + item.bpm * item.weight, 0) / Math.max(0.000001, weightTotal);\n    }\n    const expandedRawRows = expandedClusters.map((cluster) => {\n        const bpm = cluster.bpm;\n        const supports = layerSpecs.map((layer) => normalizedCorrelationSupport(layer.values, envelope.hopSeconds, bpm));\n        const phase = phaseCoherenceAtBpm(peaks, bpm, 0).score;\n        const directVotes = layerEstimates.filter((layer) => layer.estimate && tempoClose(layer.estimate.bpm, bpm)).length / layerEstimates.length;\n        return { bpm, supports, phase, directVotes, cluster };\n    });\n    const expandedMaxPhase = Math.max(...expandedRawRows.map((row) => row.phase), 0.000001);\n    const researchMetricalCandidates = expandedRawRows.map((row) => {\n        const meanSupport = row.supports.reduce((sum, value) => sum + value, 0) / row.supports.length;\n        const medianSupport = median(row.supports);\n        const strongLayers = row.supports.filter((value) => value >= 0.8).length;\n        const phaseSupport = clamp01(row.phase / expandedMaxPhase);\n        const score = clamp01(0.4 * medianSupport + 0.25 * meanSupport + 0.25 * phaseSupport + 0.1 * row.directVotes);\n        return {\n            bpm: Number(row.bpm.toFixed(3)), score: Number(score.toFixed(4)),\n            medianSupport: Number(medianSupport.toFixed(4)), meanSupport: Number(meanSupport.toFixed(4)),\n            phaseSupport: Number(phaseSupport.toFixed(4)), rawPhase: Number(row.phase.toFixed(6)),\n            strongLayers, directVotes: Number(row.directVotes.toFixed(4)),\n            seedWeight: Number(row.cluster.seeds.reduce((sum, item) => sum + item.weight, 0).toFixed(4)),\n            transforms: [...new Set(row.cluster.seeds.map((item) => item.transform))].sort(),\n        };\n    }).sort((left, right) => right.score - left.score).slice(0, 32);\n    const hybridRow = rows.find((row) => tempoClose(row.bpm, hybrid.bpm)) ?? rows[0];\n"""
if anchor not in s: raise SystemExit('selector anchor not found')
s=s.replace(anchor,insert,1)
anchor2="""        runnerUpScore: Number((runnerUp?.score ?? 0).toFixed(4)),\n    };\n"""
rep2="""        runnerUpScore: Number((runnerUp?.score ?? 0).toFixed(4)),\n        researchMetricalCandidates,\n    };\n"""
if anchor2 not in s: raise SystemExit('return anchor not found')
s=s.replace(anchor2,rep2,1)
anchor3="""            layeredPulseRunnerUpScore: layeredPulse.runnerUpScore,\n        },\n"""
rep3="""            layeredPulseRunnerUpScore: layeredPulse.runnerUpScore,\n            researchMetricalCandidates: layeredPulse.researchMetricalCandidates,\n        },\n"""
if anchor3 not in s: raise SystemExit('diagnostics anchor not found')
s=s.replace(anchor3,rep3,1)
p.write_text(s)
print(f'instrumented {p}')
